/* eslint-disable @next/next/no-img-element */

/**
 * Brand logos (via better-icons / Iconify: logos + simple-icons).
 *
 * - Full-colour marks (Gmail, Google Calendar, LinkedIn) keep their own fills
 *   and render the same in light/dark.
 * - Monochrome marks (Cal.com, Greenhouse, Resend, and the AI providers) use
 *   `currentColor`, so they tint to the surrounding text colour.
 *
 * Sized via className (default `size-5`); the last size class wins.
 */

import { cn } from "@/lib/utils";

type IconProps = { className?: string };

/* ── Integration brands ───────────────────────────────────────────────────── */

const THESVG_BASE = "https://cdn.jsdelivr.net/gh/glincker/thesvg@main/public/icons";

export function TheSvgLogo({
  slug,
  alt,
  className,
  variant = "default",
}: IconProps & { slug: string; alt: string; variant?: string }) {
  return (
    <img
      src={`${THESVG_BASE}/${slug}/${variant}.svg`}
      alt={alt}
      className={cn("size-5", className)}
      aria-hidden="true"
    />
  );
}

