export function DocuSealLogo({ className }: IconProps) {
  // DocuSeal has no theSVG entry; inline mark — a signed document sheet with a
  // check seal, in DocuSeal's indigo. currentColor-free so it reads on any tile.
  return (
    <svg
      viewBox="0 0 24 24"
      className={cn("size-5", className)}
      fill="none"
      aria-hidden="true"
    >
      <path
        d="M6 2.75h7.2L18 7.4v10.35A2.25 2.25 0 0 1 15.75 20H6a2.25 2.25 0 0 1-2.25-2.25V5A2.25 2.25 0 0 1 6 2.75Z"
        fill="#1A56DB"
      />
      <path d="M13 3v4.25h4.4L13 3Z" fill="#1E429F" />
      <path
        d="m8 12.6 2 2 4.2-4.4"
        stroke="#fff"
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

